-- CV-matching published projects. Apply after all portfolio migrations. Existing GitHub edits are preserved.
begin;
update public.projects set title='S2 TURBO', description='An automotive customization platform with a parts catalog and interactive 3D garage. Includes compatible-part previews, before-and-after comparisons, saved configurations, and performance estimates.', image_url='/assets/projects/s2-turbo.jpg', live_url='https://s2-turbo-performance.nooringyby.chatgpt.site/', is_published=true, is_featured=true, display_order=0 where live_url='https://s2-turbo-performance.nooringyby.chatgpt.site/';
insert into public.projects (title, description, image_url, live_url,is_published,is_featured,display_order,github_url) select 'S2 TURBO', 'An automotive customization platform with a parts catalog and interactive 3D garage. Includes compatible-part previews, before-and-after comparisons, saved configurations, and performance estimates.', '/assets/projects/s2-turbo.jpg', 'https://s2-turbo-performance.nooringyby.chatgpt.site/',true,true,0,null where not exists(select 1 from public.projects where live_url='https://s2-turbo-performance.nooringyby.chatgpt.site/');
update public.projects set title='Bikhtisar', description='An Arabic news website with editorial roles, content review, approval, and scheduled publishing. Its Android/iOS app connects to the same backend for news, stories, reports, and search.', image_url='/assets/projects/bikhtisar.jpg', live_url='https://www.bikhtisar.site/', is_published=true, is_featured=false, display_order=1 where live_url='https://www.bikhtisar.site/';
insert into public.projects (title, description, image_url, live_url,is_published,is_featured,display_order,github_url) select 'Bikhtisar', 'An Arabic news website with editorial roles, content review, approval, and scheduled publishing. Its Android/iOS app connects to the same backend for news, stories, reports, and search.', '/assets/projects/bikhtisar.jpg', 'https://www.bikhtisar.site/',true,false,1,'https://github.com/NoorFarra/bakhtesar' where not exists(select 1 from public.projects where live_url='https://www.bikhtisar.site/');
update public.projects set title='Wajehti Platform', description='An Arabic dashboard combining website shortcuts and search with currency exchange rates, Ramallah weather, and daily prayer times.', image_url='/assets/projects/wajehti.jpg', live_url='https://wajehtii.vercel.app/', is_published=true, is_featured=false, display_order=2 where live_url='https://wajehtii.vercel.app/';
insert into public.projects (title, description, image_url, live_url,is_published,is_featured,display_order,github_url) select 'Wajehti Platform', 'An Arabic dashboard combining website shortcuts and search with currency exchange rates, Ramallah weather, and daily prayer times.', '/assets/projects/wajehti.jpg', 'https://wajehtii.vercel.app/',true,false,2,'https://github.com/NoorFarra/Wajehti' where not exists(select 1 from public.projects where live_url='https://wajehtii.vercel.app/');
commit;
